1	import { CanActivate, ExecutionContext, Injectable, ForbiddenException } from '@nestjs/common';
2	import { JwtGuard } from './jwt.guard';
3	import { SupabaseService } from '../supabase/supabase.service';
4	import { CorsOriginsService } from '../common/cors-origins.service';
5	import { normalizarDominio } from '../common/dominio.util';
6	
7	@Injectable()
8	export class RestaurantOwnerGuard implements CanActivate {
9	  constructor(
10	    private jwtGuard: JwtGuard,
11	    private supabase: SupabaseService,
12	    private corsOrigins: CorsOriginsService,
13	  ) {}
14	
15	  async canActivate(context: ExecutionContext): Promise<boolean> {
16	    await this.jwtGuard.canActivate(context);
17	
18	    const request = context.switchToHttp().getRequest();
19	    const userId: string = request.userId;
20	
21	    const { data } = await this.supabase.client
22	      .from('restaurants')
23	      .select('id')
24	      .eq('user_id', userId)
25	      .maybeSingle();
26	
27	    if (!data) {
28	      throw new ForbiddenException('Nenhum restaurante vinculado a este usuário');
29	    }
30	
31	    // Domínio White Label (ex: recantodofarol.teusite.top) pertence a UMA loja só. O
32	    // navegador manda a origem automaticamente (Origin/Referer não são editáveis por
33	    // JS de terceiros) — se ela pertence a outra loja, as credenciais logadas não
34	    // podem operar ali, mesmo sendo válidas (bug real encontrado em produção:
35	    // dono de qualquer loja conseguia logar no domínio de outra e ver seu próprio painel).
36	    const origem = request.headers['origin'] || request.headers['referer'];
37	    // Domínio "base" da plataforma (app principal/dev) é compartilhado por TODAS as
38	    // lojas, não é White Label de nenhuma específica — pular a checagem de posse do
39	    // custom_domain aqui, senão qualquer loja cujo custom_domain bata (por acidente
40	    // de cadastro, ou simplesmente por ainda não ter loja nenhuma com domínio próprio
