import React, { useState, useEffect, useCallback } from 'react';
import {
  listarImpressoras, criarImpressora, atualizarImpressora, removerImpressora,
  getImpressorasDetectadas, gerarTokenAgente, getStatusAgente, testarImpressora,
  renovarTokenImpressora,
} from '../../services/restauranteService';
import RestauranteHeader from '../../components/restaurante/RestauranteHeader';

export const AgenteImpressaoPanel = () => {
  const [status, setStatus] = useState(null);
  const [token, setToken] = useState(null);
  const [gerando, setGerando] = useState(false);
  const [copiado, setCopiado] = useState(false);

  const carregarStatus = useCallback(() => getStatusAgente().then(setStatus).catch(() => {}), []);
  useEffect(() => {
    carregarStatus();
    const interval = setInterval(carregarStatus, 15000);
    return () => clearInterval(interval);
  }, [carregarStatus]);

  const gerar = async () => {
    setGerando(true);
    try {
      const { token } = await gerarTokenAgente();
      setToken(token);
      carregarStatus();
    } finally {
      setGerando(false);
    }
  };

  const copiar = () => {
    navigator.clipboard?.writeText(token);
    setCopiado(true);
    setTimeout(() => setCopiado(false), 2000);
  };

  return (
    <div className="bg-white dark:bg-[#27272A] rounded-2xl border border-[#E4E4E7] dark:border-[#3F3F46] p-4 mb-4">
      <div className="flex items-center justify-between mb-2">
        <p className="text-sm font-bold text-[#18181B] dark:text-[#F4F4F5]">Agente de impressão local</p>
        {status && (
          <span className={`text-[10px] px-2 py-1 rounded-full font-medium ${status.online ? 'bg-emerald-100 dark:bg-emerald-950/40 text-emerald-700 dark:text-emerald-400' : 'bg-zinc-100 dark:bg-zinc-950/40 text-zinc-500 dark:text-zinc-400'}`}>
            {status.online ? 'Online' : status.pareado ? 'Offline' : 'Não pareado'}
          </span>
        )}
      </div>
      <ol className="text-xs text-[#71717A] dark:text-[#A1A1AA] space-y-1.5 mb-3 list-decimal list-inside">
        <li>
          <a href="/print-agent.rar" download className="text-[#FF441F] font-semibold">Baixe o agente (print-agent.rar)</a>
          {' '}no PC onde as impressoras estão instaladas ou conectadas.
        </li>
        <li>Descompacte o arquivo baixado (botão direito → Extrair aqui).</li>
        <li>Abra a pasta <strong>print-agent</strong>.</li>
        <li>Abra a pasta <strong>releases</strong>.</li>
        <li>Dê duplo clique em <strong>DeliveryHubAgente.exe</strong> para abrir o agente.</li>
        <li>Clique em <strong>"Gerar token de pareamento"</strong> abaixo, copie a chave e cole na janela do agente para conectar as impressoras.</li>
      </ol>
      <p className="text-xs text-[#A1A1AA] mb-3">
        💡 Dica: crie um atalho do <strong>DeliveryHubAgente.exe</strong> na área de trabalho para abrir o agente rapidamente da próxima vez.
      </p>
      <p className="text-xs text-[#A1A1AA] mb-3">
        <a href="https://github.com/jmoka/deliveryhub_white_label/tree/main/print-agent" target="_blank" rel="noreferrer" className="text-[#FF441F] font-semibold">Documentação completa</a>
      </p>
      <button onClick={gerar} disabled={gerando}
        className="px-4 py-2 bg-zinc-800 text-white text-sm font-bold rounded-xl disabled:opacity-50">
        {gerando ? 'Gerando...' : 'Gerar token de pareamento'}
      </button>
      {token && (
        <div className="flex items-center gap-2 mt-3 bg-[#F4F4F5] dark:bg-[#3F3F46] rounded-xl px-3 py-2">
          <span className="text-xs font-mono text-[#71717A] dark:text-[#A1A1AA] truncate flex-1">{token}</span>
          <button onClick={copiar} className="text-xs font-bold text-[#FF441F]">{copiado ? 'Copiado!' : 'Copiar'}</button>
        </div>
      )}
    </div>
  );
};

const RestauranteImpressoras = () => {
  const [impressoras, setImpressoras] = useState([]);
  const [detectadas, setDetectadas] = useState([]);
  const [nome, setNome] = useState('');
  const [setor, setSetor] = useState('');
  const [tipoConexao, setTipoConexao] = useState('rede');
  const [endereco, setEndereco] = useState('');
  const [nomeSistema, setNomeSistema] = useState('');
  const [erro, setErro] = useState(null);

  const carregar = useCallback(() => {
    listarImpressoras().then(setImpressoras);
    getImpressorasDetectadas().then(setDetectadas).catch(() => {});
  }, []);
  useEffect(() => { carregar(); }, [carregar]);

  const criar = async (e) => {
    e.preventDefault();
    setErro(null);
    try {
      await criarImpressora({
        nome, setor, tipo_conexao: tipoConexao,
        endereco: endereco || undefined,
        nome_sistema: nomeSistema || undefined,
      });
      setNome(''); setSetor(''); setEndereco(''); setNomeSistema('');
      carregar();
    } catch (err) {
      setErro(err.message);
    }
  };

  const toggleAtiva = async (imp) => {
    await atualizarImpressora(imp.id, { ativo: !imp.ativo });
    carregar();
  };

  const vincularDetectada = async (id, nomeSistema) => {
    await atualizarImpressora(id, { nome_sistema: nomeSistema || null });
    carregar();
  };

  const remover = async (id) => {
    if (!window.confirm('Remover esta impressora?')) return;
    await removerImpressora(id);
    carregar();
  };

  const [gerandoToken, setGerandoToken] = useState(null);
  const [copiadoId, setCopiadoId] = useState(null);
  const gerarToken = async (id) => {
    setGerandoToken(id);
    try {
      await renovarTokenImpressora(id);
      carregar();
    } catch (err) {
      alert('Erro ao gerar token: ' + err.message);
    } finally {
      setGerandoToken(null);
    }
  };

  const copiarLink = (imp) => {
    navigator.clipboard?.writeText(linkKds(imp));
    setCopiadoId(imp.id);
    setTimeout(() => setCopiadoId(null), 2000);
  };

  const [testando, setTestando] = useState(null);
  const testar = async (id) => {
    setTestando(id);
    try {
      await testarImpressora(id);
      alert('Teste enviado! O agente deve imprimir em alguns segundos.');
    } catch (err) {
      alert(err.message);
    } finally {
      setTestando(null);
    }
  };

  const linkKds = (imp) => `${window.location.origin}/restaurante/kds?impressora_id=${imp.id}&setor=${encodeURIComponent(imp.setor)}${imp.token ? `&cozinha_token=${imp.token}` : ''}`;

  return (
    <div className="min-h-screen bg-[#F4F4F5] dark:bg-[#18181B]">
      <RestauranteHeader active="/restaurante/impressoras" title="Impressoras" onRefresh={carregar} />
      <div className="max-w-4xl mx-auto p-4">
        <AgenteImpressaoPanel />

        <form onSubmit={criar} className="bg-white dark:bg-[#27272A] rounded-2xl border border-[#E4E4E7] dark:border-[#3F3F46] p-4 mb-4 flex flex-wrap gap-2 items-end">
          <div className="flex-1 min-w-[120px]">
            <label className="text-xs text-[#71717A] dark:text-[#A1A1AA]">Nome</label>
            <input value={nome} onChange={(e) => setNome(e.target.value)} required placeholder="Ex: Impressora Bar"
              className="w-full border border-[#E4E4E7] dark:border-[#3F3F46] bg-white dark:bg-[#18181B] text-[#18181B] dark:text-[#F4F4F5] rounded-xl px-3 py-2 text-sm" />
          </div>
          <div className="flex-1 min-w-[120px]">
            <label className="text-xs text-[#71717A] dark:text-[#A1A1AA]">Setor</label>
            <input value={setor} onChange={(e) => setSetor(e.target.value)} required placeholder="Ex: bar, cozinha, salgados"
              className="w-full border border-[#E4E4E7] dark:border-[#3F3F46] bg-white dark:bg-[#18181B] text-[#18181B] dark:text-[#F4F4F5] rounded-xl px-3 py-2 text-sm" />
          </div>
          <div>
            <label className="text-xs text-[#71717A] dark:text-[#A1A1AA]">Conexão</label>
            <select value={tipoConexao} onChange={(e) => setTipoConexao(e.target.value)}
              className="border border-[#E4E4E7] dark:border-[#3F3F46] bg-white dark:bg-[#18181B] text-[#18181B] dark:text-[#F4F4F5] rounded-xl px-3 py-2 text-sm">
              <option value="rede">Rede</option>
              <option value="local">Local (USB)</option>
            </select>
          </div>
          {detectadas.length > 0 ? (
            <div className="flex-1 min-w-[160px]">
              <label className="text-xs text-[#71717A] dark:text-[#A1A1AA]">Impressora detectada pelo agente</label>
              <select value={nomeSistema} onChange={(e) => setNomeSistema(e.target.value)}
                className="w-full border border-[#E4E4E7] dark:border-[#3F3F46] bg-white dark:bg-[#18181B] text-[#18181B] dark:text-[#F4F4F5] rounded-xl px-3 py-2 text-sm">
                <option value="">Nenhuma (manual/rede)</option>
                {detectadas.map((d) => (
                  <option key={d.id} value={d.nome_sistema}>{d.nome_sistema}</option>
                ))}
              </select>
            </div>
          ) : (
            <div className="flex-1 min-w-[120px]">
              <label className="text-xs text-[#71717A] dark:text-[#A1A1AA]">Endereço (IP ou nome)</label>
              <input value={endereco} onChange={(e) => setEndereco(e.target.value)}
                className="w-full border border-[#E4E4E7] dark:border-[#3F3F46] bg-white dark:bg-[#18181B] text-[#18181B] dark:text-[#F4F4F5] rounded-xl px-3 py-2 text-sm" />
            </div>
          )}
          {erro && <p className="text-xs text-red-600 dark:text-red-400 w-full">{erro}</p>}
          <button type="submit" className="px-4 py-2 bg-[#FF441F] text-white text-sm font-bold rounded-xl">Adicionar</button>
        </form>

        <div className="grid grid-cols-1 sm:grid-cols-2 gap-3">
          {impressoras.map((imp) => (
            <div key={imp.id} className="bg-white dark:bg-[#27272A] rounded-2xl border border-[#E4E4E7] dark:border-[#3F3F46] p-4">
              <div className="flex justify-between items-start">
                <div>
                  <p className="text-sm font-bold text-[#18181B] dark:text-[#F4F4F5]">{imp.nome}</p>
                  <p className="text-xs text-[#71717A] dark:text-[#A1A1AA]">Setor: {imp.setor} · {imp.tipo_conexao}</p>
                  {imp.nome_sistema
                    ? <p className="text-xs text-emerald-700 dark:text-emerald-400">🖨 {imp.nome_sistema} (agente)</p>
                    : imp.endereco && <p className="text-xs text-[#A1A1AA]">{imp.endereco}</p>}
                </div>
                <span className={`text-[10px] px-2 py-1 rounded-full font-medium ${imp.ativo ? 'bg-emerald-100 dark:bg-emerald-950/40 text-emerald-700 dark:text-emerald-400' : 'bg-zinc-100 dark:bg-zinc-950/40 text-zinc-500 dark:text-zinc-400'}`}>
                  {imp.ativo ? 'Ativa' : 'Inativa'}
                </span>
              </div>

              {detectadas.length > 0 && (
                <div className="mt-3">
                  <label className="text-xs text-[#71717A] dark:text-[#A1A1AA]">Vincular impressora detectada</label>
                  <select value={imp.nome_sistema ?? ''} onChange={(e) => vincularDetectada(imp.id, e.target.value)}
                    className="w-full border border-[#E4E4E7] dark:border-[#3F3F46] bg-white dark:bg-[#18181B] text-[#18181B] dark:text-[#F4F4F5] rounded-xl px-3 py-2 text-sm mt-1">
                    <option value="">Nenhuma (manual/rede)</option>
                    {detectadas.map((d) => (
                      <option key={d.id} value={d.nome_sistema}>{d.nome_sistema}</option>
                    ))}
                  </select>
                </div>
              )}
              {imp.token ? (
                <>
                  <div className="flex items-center gap-2 mt-3 bg-[#F4F4F5] dark:bg-[#3F3F46] rounded-xl px-3 py-2">
                    <span className="text-xs font-mono text-[#71717A] dark:text-[#A1A1AA] truncate flex-1">{linkKds(imp)}</span>
                    <button onClick={() => copiarLink(imp)} className="text-xs font-bold text-[#FF441F] flex-shrink-0">
                      {copiadoId === imp.id ? 'Copiado!' : 'Copiar'}
                    </button>
                  </div>
                  <button onClick={() => gerarToken(imp.id)} disabled={gerandoToken === imp.id}
                    className="text-[10px] text-[#71717A] dark:text-[#A1A1AA] mt-1 hover:underline disabled:opacity-50">
                    {gerandoToken === imp.id ? 'Gerando...' : 'Gerar novo token (invalida o link atual deste setor)'}
                  </button>
                </>
              ) : (
                <button onClick={() => gerarToken(imp.id)} disabled={gerandoToken === imp.id}
                  className="w-full mt-3 py-1.5 text-xs font-bold border border-[#FF441F] text-[#FF441F] rounded-lg hover:bg-[#FF441F]/5 disabled:opacity-50">
                  {gerandoToken === imp.id ? 'Gerando...' : 'Gerar token de acesso (KDS)'}
                </button>
              )}
              {imp.nome_sistema && (
                <button onClick={() => testar(imp.id)} disabled={testando === imp.id}
                  className="w-full mt-3 py-1.5 text-xs font-bold border border-[#FF441F] text-[#FF441F] rounded-lg hover:bg-[#FF441F]/5 disabled:opacity-50">
                  {testando === imp.id ? 'Enviando...' : '🖨 Testar impressão'}
                </button>
              )}
              <div className="flex gap-2 mt-3">
                <button onClick={() => toggleAtiva(imp)} className="flex-1 py-1.5 text-xs border border-[#E4E4E7] dark:border-[#3F3F46] rounded-lg text-[#71717A] dark:text-[#A1A1AA] hover:bg-[#F4F4F5] dark:hover:bg-[#3F3F46]">
                  {imp.ativo ? 'Desativar' : 'Ativar'}
                </button>
                <button onClick={() => remover(imp.id)} className="flex-1 py-1.5 text-xs border border-red-200 dark:border-red-800 text-red-600 dark:text-red-400 rounded-lg hover:bg-red-50 dark:hover:bg-red-950/40">
                  Remover
                </button>
              </div>
            </div>
          ))}
          {impressoras.length === 0 && <p className="text-sm text-[#A1A1AA]">Nenhuma impressora cadastrada.</p>}
        </div>
      </div>
    </div>
  );
};

export default RestauranteImpressoras;

