import { supabase } from '../lib/supabase';
import { apiPath } from '../lib/apiUrl';

const API = apiPath('/api/restaurante');

async function apiFetch(path, options = {}) {
  const sessionResult = await supabase.auth.getSession().catch(() => ({ data: {} }));
  const token = sessionResult?.data?.session?.access_token;

  if (!token) throw new Error('Sessão expirada. Faça login novamente.');

  const res = await fetch(`${API}${path}`, {
    ...options,
    headers: {
      'Content-Type': 'application/json',
      'Authorization': `Bearer ${token}`,
      ...options.headers,
    },
  });

  const contentType = res.headers.get('content-type') ?? '';
  const isJson = contentType.includes('application/json');

  if (!res.ok) {
    const err = isJson ? await res.json().catch(() => ({})) : {};
    const error = new Error(err?.message ?? `HTTP ${res.status}`);
    error.data = err;
    throw error;
  }

  if (!isJson) throw new Error('Resposta inválida. Verifique se o backend está rodando.');

  return res.json();
}

export const registrarRestauranteInicial = (data) =>
  apiFetch('/registrar-inicial', { method: 'POST', body: JSON.stringify(data) });

export const finalizarCadastroRestaurante = (data) =>
  apiFetch('/finalizar', { method: 'POST', body: JSON.stringify(data) });

export const verificarDisponibilidadeCadastro = (data) =>
  apiFetch('/verificar-disponibilidade', { method: 'POST', body: JSON.stringify(data) });

export const getMinhaEmpresa = () => apiFetch('/minha-empresa');

